// 1. Извлекаем массив всех входящих элементов
const items = $input.all();
if (!items || items.length === 0) {
  return [];
}

const item = items[0];
const binaryData = item.binary;

// Проверяем наличие бинарных файлов
if (!binaryData || !binaryData.file || !binaryData.rules) {
  throw new Error("Missing 'file' or 'rules' binary parameter in request.");
}

// 2. Читаем бинарные данные по имени ключа
const logBuffer = await this.helpers.getBinaryDataBuffer(0, 'file');
const logText = logBuffer.toString('utf-8');

const rulesBuffer = await this.helpers.getBinaryDataBuffer(0, 'rules');
const rulesJson = JSON.parse(rulesBuffer.toString('utf-8'));

// 3. Извлекаем log_type с защитой от сдвига аргументов
const body = $('Webhook').item?.json?.body || {};
let logType = body.type || 'ssh';

if (!logType || typeof logType !== 'string' || logType.endsWith('.json')) {
  logType = 'ssh';
}

// 4. Разбиваем лог на строки
const lines = logText.split(/\r?\n/).filter(line => line.trim() !== '');

if (lines.length === 0) {
  return [
    {
      json: {
        log_line: '',
        type: logType,
        rules: rulesJson,
        is_empty: true
      }
    }
  ];
}

// 5. Возвращаем обычный массив объектов { json: ... }
const output = lines.map(line => ({
  json: {
    log_line: line,
    type: logType,
    rules: rulesJson
  }
}));

return [
  {
    json: {
      log_line: logText,
      type: logType,
      rules: rulesJson
    }
  }
];

