const inputItem = $json || {};

const logType = String(inputItem.type || 'ssh').toLowerCase();
const logLine = String(inputItem.log_line || '');

let rulesJson = inputItem.rules || {};

if (typeof rulesJson === 'string') {
  try {
    rulesJson = JSON.parse(rulesJson);
  } catch (e) {
    console.error('Ошибка парсинга rules:', e.message);
    rulesJson = {};
  }
}

const patternsL1 = rulesJson[logType]?.level_1 || [];
const patternsL2 = rulesJson[logType]?.level_2 || [];

const checkRules = (patterns, level) => {
  const matches = [];

  if (!Array.isArray(patterns)) return matches;

  for (const pattern of patterns) {
    try {
      const flags = logType === 'journalctl' ? 'gi' : 'g';
      const regex = new RegExp(pattern, flags);

      let match;
      while ((match = regex.exec(logLine)) !== null) {
        matches.push({
          level,
          rule: pattern,
          matched_text: match[0],
        });

        // Защита от бесконечного цикла для некоторых regex
        if (match[0] === '') {
          regex.lastIndex++;
        }
      }
    } catch (e) {
      console.error(`Ошибка обработки правила ${pattern}: ${e.message}`);
    }
  }

  return matches;
};

const level1Matches = checkRules(patternsL1, 1);
const level2Matches = checkRules(patternsL2, 2);

return {
  json: {
    log_line: logLine,
    log_type: logType,
    patterns_l1: patternsL1,
    patterns_l2: patternsL2,
    is_suspicious: level1Matches.length > 0,
    is_really_suspicious: level2Matches.length > 0,
    matched_rules: [...level1Matches, ...level2Matches],
  }
};
